package com.greenocean.backend;
import com.greenocean.backend.trust.*;import com.greenocean.backend.professional.service.*;import com.greenocean.backend.common.exception.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;import java.util.*;import static org.assertj.core.api.Assertions.*;

@SpringBootTest(properties={"greenocean.trust.enabled=true","greenocean.clinic.commerce-enabled=true","greenocean.clinic.records-enabled=true","greenocean.clinic.record-keys=clinical-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.record-current-key=clinical-qa","greenocean.clinic.reputation-enabled=true","greenocean.clinic.public-reputation-enabled=true","greenocean.clinic.reputation-keys=reputation-qa:AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA=","greenocean.clinic.reputation-current-key=reputation-qa"}) @AutoConfigureMockMvc @ActiveProfiles("test") @Transactional
class PhaseQ1SourceIsolationTest extends PhaseP4Fixtures {
 @Autowired TrustCases cases;@Autowired TrustSources sources;@Autowired ClinicIntegration integration;
 @BeforeEach void scopes(){for(var a:List.of(issuer,reviewer,other)){for(String role:List.of("TRUST_CLINIC","TRUST_FINANCE","TRUST_ACCOUNT","TRUST_EDUCATION","TRUST_PLATFORM","CLINIC_OPERATIONS"))role(a.id(),role);db.update("UPDATE user_sessions SET mfa_authenticated_at=CURRENT_TIMESTAMP WHERE id=?",a.session());}}
 @Test void clinicIncidentAndPaymentQueuesStayPurposeIsolated(){UUID incident=integration.incident(learner.id(),learner.session(),appointment,"CONNECTION"),payment=integration.incident(learner.id(),learner.session(),appointment,"PAYMENT");UUID c=cases.coordinate(issuer.id(),issuer.session(),"CLINIC_INCIDENT",incident,"CLINIC");assertThatThrownBy(()->cases.coordinate(issuer.id(),issuer.session(),"CLINIC_INCIDENT",payment,"CLINIC")).isInstanceOf(NotFoundException.class);assertThat(cases.coordinate(issuer.id(),issuer.session(),"CLINIC_INCIDENT",payment,"FINANCE")).isNotNull();String serialized=cases.detail(issuer.id(),issuer.session(),c,"CLINIC").toString();assertThat(serialized).doesNotContain(learner.id().toString(),author.id().toString(),"requester_user_id","body_cipher","patient_id");}
 @Test void professionalComplaintCoordinationNeverDecryptsItsEvidence(){UUID source=reputation.openCase(learner.id(),author.id(),null,appointment,"CONDUCT","SYNTHETIC_PRIVATE_PROFESSIONAL_COMPLAINT");UUID id=cases.coordinate(issuer.id(),issuer.session(),"REPUTATION_CASE",source,"CLINIC");assertThat(cases.detail(issuer.id(),issuer.session(),id,"CLINIC").toString()).doesNotContain("SYNTHETIC_PRIVATE_PROFESSIONAL_COMPLAINT",learner.id().toString(),author.id().toString(),"body_cipher");assertThat(sources.read("REPUTATION_CASE",source).complete()).isFalse();}
 @Test void laterUnapprovedClinicEvidencePreventsCompletedOutcomeClaim(){UUID incident=integration.incident(learner.id(),learner.session(),appointment,"CONNECTION");UUID review=integration.incidentReview(reviewer.id(),reviewer.session(),incident,"NO_OUTAGE","SYNTHETIC-INDEPENDENT-EVIDENCE");integration.approveIncident(other.id(),other.session(),review);assertThat(sources.read("CLINIC_INCIDENT",incident).complete()).isTrue();integration.incidentReview(issuer.id(),issuer.session(),incident,"UNRESOLVED","SYNTHETIC-NEW-INDEPENDENT-EVIDENCE");assertThat(sources.read("CLINIC_INCIDENT",incident).complete()).isFalse();}
 @Test void educationalAndPlatformSourceReferencesRetainOnlyTheSelectedPurpose(){UUID source=db.queryForObject("INSERT INTO support_requests(user_id,email,message) VALUES(?,'synthetic-complaint@example.test','SYNTHETIC_EDUCATIONAL_PRIVATE_NARRATIVE') RETURNING id",UUID.class,learner.id());UUID id=cases.coordinate(issuer.id(),issuer.session(),"SUPPORT_REQUEST",source,"EDUCATION");assertThat(cases.detail(issuer.id(),issuer.session(),id,"EDUCATION").toString()).contains("EDUCATIONAL_CONTENT").doesNotContain("SYNTHETIC_EDUCATIONAL_PRIVATE_NARRATIVE","synthetic-complaint@example.test");assertThatThrownBy(()->cases.coordinate(issuer.id(),issuer.session(),"SUPPORT_REQUEST",source,"PLATFORM")).isInstanceOf(ConflictException.class);}
}
